package com.aaliyun.leadnews.wemedia.service;import com.aaliyun.leadnews.common.exception.BusinessException;import org.junit.jupiter.api.Test;import java.awt.image.BufferedImage;import java.io.ByteArrayOutputStream;import javax.imageio.ImageIO;import static org.assertj.core.api.Assertions.*;class MaterialStorageServiceTest{@Test void detectsPngByBytesNotFilename(){byte[] png={(byte)137,80,78,71,13,10,26,10};assertThat(MaterialStorageService.detect(png).mime()).isEqualTo("image/png");}@Test void rejectsHtmlBytes(){assertThatThrownBy(()->MaterialStorageService.detect("<html>".getBytes())).isInstanceOf(BusinessException.class);}@Test void rejectsExcessivePixelCount()throws Exception{var image=new BufferedImage(100,100,BufferedImage.TYPE_INT_RGB);var out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);assertThatThrownBy(()->MaterialStorageService.validateDimensions(out.toByteArray(),9999)).isInstanceOf(BusinessException.class);MaterialStorageService.validateDimensions(out.toByteArray(),10000);}}
